import { extractFrontMatter, stringifyYaml, testFrontMatter } from "../../deps/std.js";
import { TransformError } from "./transform-error.js";
export const FrontMatter = {
    toData(content) {
        try {
            if (testFrontMatter(content, ["yaml"])) {
                const { attrs, body } = extractFrontMatter(content);
                const data = {};
                Object.assign(data, attrs);
                data.content = body;
                return data;
            }
        }
        catch (error) {
            throw new TransformError(`Malformed front matter code (YAML): ${error.message}`);
        }
        return { content };
    },
    fromData(data) {
        const { content, ...attrs } = data ?? {};
        const body = String(content || "").trimEnd() + "\n";
        if (Object.keys(attrs).length === 0) {
            return body;
        }
        return `---\n${stringifyYaml(attrs)}---\n${body}`;
    },
};
